class MessageOwner(object):
    MessageOwner_instances = {}

    def __new__(cls, *args, **kwargs):
        if args and not kwargs:
            dev_name, dev_id = MessageOwner.__get_dev_from_args(*args)

        if kwargs and not args:
            dev_name, dev_id = MessageOwner.__get_dev_from_kwargs(**kwargs)

        owner_name = dev_name + str(dev_id)

        if owner_name not in cls.MessageOwner_instances:
            self = super(MessageOwner, cls).__new__(cls)
            self.initialized = False
            cls.MessageOwner_instances[owner_name] = self
        return cls.MessageOwner_instances[owner_name]

    def __init__(self, device_name, device_id=None):
        if self.initialized:  # pylint: disable=E0203
            return
        self.device_name = device_name
        self.device_id = str(device_id) if device_id is not None else device_id
        self.initialized = True

    def __eq__(self, other):
        return (self.device_name == other.device_name) and \
               (self.device_id == other.device_id or self.device_id is None or other.device_id is None)

    def __str__(self):
        output = '%s%s' % (str(self.device_name), str(self.device_id))
        return output

    @staticmethod
    def __get_dev_from_args(*args):
        dev_name = str(args[0])
        if len(args) > 1:
            dev_id = str(args[1])
        else:
            dev_id = None
        return dev_name, dev_id

    @staticmethod
    def __get_dev_from_kwargs(**kwargs):
        dev_name = str(kwargs.get('device_name'))
        if 'device_id' in kwargs and kwargs.get('device_id') is not None:
            dev_id = str(kwargs.get('device_id'))
        else:
            dev_id = None
        return dev_name, dev_id
